import '../data/app_store.dart';import '../models/models.dart';
class AssistantAnswer{final String text;final List<String> sources;const AssistantAnswer(this.text,this.sources);}
class OperonAssistant{final AppStore store;OperonAssistant(this.store);
AssistantAnswer ask(String question){final q=question.toUpperCase(),tag=_tag(q);if(tag!=null)return _equipment(tag);if(q.contains('SHIFT')||q.contains('ΒΑΡΔ')||q.contains('ΠΡΟΣΕΞ')||q.contains('KNOW'))return _shift();if(q.contains('OVERDUE')||q.contains('ΕΚΠΡΟΘ'))return _overdue();return const AssistantAnswer('I can answer from OPERON records. Ask about a TAG, the current shift, carried/overdue actions, maintenance or recorded operational knowledge.',['OPERON local records']);}
String? _tag(String q){for(final e in store.equipment){final a=e.tag.toUpperCase(),compact=a.replaceAll(RegExp(r'[^A-Z0-9]'),'');if(q.contains(a)||q.replaceAll(RegExp(r'[^A-Z0-9]'),'').contains(compact))return e.tag;}return null;}
AssistantAnswer _equipment(String tag){final e=store.equipment.firstWhere((x)=>x.tag==tag),k=store.knowledge[tag],tasks=store.tasks.where((x)=>x.equipmentTag==tag&&x.state!=ActionState.completed),watch=store.watch.where((x)=>x.equipmentTag==tag&&x.active),logs=store.logs.where((x)=>x.equipmentTag==tag).take(5);final circuits=store.circuitsForTag(tag);final notes=store.notes.where((x)=>x.equipmentTag==tag&&!x.resolved);final b=StringBuffer()..writeln('$tag · ${e.name}')..writeln('Recorded state: ${e.state.name}')..writeln(e.note.isEmpty?'Active note: none':'Active note: ${e.note}');if(tasks.isNotEmpty)b..writeln('\nOpen actions:')..writeAll(tasks.map((x)=>'• ${x.title}${x.carriedShifts>0?' · carried ×${x.carriedShifts}':''}'));if(watch.isNotEmpty)b..writeln('\nWatch items:')..writeAll(watch.map((x)=>'• ${x.detail}'));if(k?.hasContent==true){b.writeln('\nRecorded operational knowledge:');if(k!.normalRange.isNotEmpty)b.writeln('• Normal range: ${k.normalRange}');if(k.valvePosition.isNotEmpty)b.writeln('• Valve/position: ${k.valvePosition}');if(k.processCircuit.isNotEmpty)b.writeln('• Circuit: ${k.processCircuit}');if(k.operatorNotes.isNotEmpty)b.writeln('• Notes: ${k.operatorNotes}');if(k.procedureRefs.isNotEmpty)b.writeln('• References: ${k.procedureRefs.join(', ')}');}if(notes.isNotEmpty){b.writeln('\nOperator notes:');for(final n in notes){b.writeln('• ${n.title}: ${n.body}');}}if(circuits.isNotEmpty){b.writeln('\nProcess context:');for(final x in circuits){final i=x.nodes.indexWhere((n)=>n.tag==tag);final up=i>0?x.nodes[i-1].tag:'START';final down=i>=0&&i<x.nodes.length-1?x.nodes[i+1].tag:'END';b.writeln('• ${x.name}: $up → $tag → $down');}}if(logs.isNotEmpty)b..writeln('\nRecent recorded events:')..writeAll(logs.map((x)=>'• ${x.text}'));return AssistantAnswer(b.toString().trim(),['Equipment registry: $tag',if(k?.hasContent==true)'Recorded operational knowledge: $tag',if(tasks.isNotEmpty)'Open actions',if(watch.isNotEmpty)'Watchlist',if(store.circuitsForTag(tag).isNotEmpty)'Process circuits','Operator log']);}
AssistantAnswer _shift(){final open=store.tasks.where((x)=>x.state!=ActionState.completed),unavailable=store.equipment.where((x)=>x.state==EquipmentState.maintenance||x.state==EquipmentState.outOfService||x.state==EquipmentState.taggedOut);return AssistantAnswer('Recorded shift picture:\n• ${open.length} open actions\n• ${store.carriedTasks.length} carried actions\n• ${store.overdueTasks.length} overdue actions\n• ${unavailable.length} unavailable / maintenance / tagged equipment\n• ${store.watch.where((x)=>x.active).length} active watch items\n\nThis summary reports OPERON records only; it is not an independent plant-state or safety determination.',['Current shift','Equipment registry','Open actions','Watchlist']);}
AssistantAnswer _overdue(){final x=store.overdueTasks;return AssistantAnswer(x.isEmpty?'No overdue actions are recorded.':x.map((e)=>'• ${e.equipmentTag??'General'} · ${e.title}').join('\n'),['Open actions']);}}
